window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3fa196727afaa99e"]={"versions": [{"id": "FIG-3fa196727afaa99e", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR-SoftwareComponentTemplate. Das Diagramm modelliert die Integration von ECU-State-Manager-Bedarfen (<code>SwcEcuStateMgrUserNeeds</code>) einer Software-Komponente in deren internes Verhalten (<code>SwcInternalBehavior::InternalBehavior</code>) sowie die Zuordnung zu konkreten Empfänger-Ports (<code>RoleBasedRPortAssignment</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SwcInternalBehavior::InternalBehavior</code> (Stereotyp «ARElement»): Enthält das Attribut <code>+ supportsMultipleInstantiation: Boolean</code>. Besitzt eine Kompositionsbeziehung über die Assoziationsrolle <code>+serviceNeeds</code> mit Multiplizität <code>0..*</code> zu <code>Identifiable / ServiceNeeds::ServiceNeeds</code>.</li>\n<li><code>ServiceNeeds::ServiceNeeds</code> (Spezialisierung von <code>Identifiable</code>): Abstrakte Basisklasse für Service-Bedarfe.</li>\n<li><code>ServiceNeeds::EcuStateMgrUserNeeds</code>: Spezialisierung (Generalisierungsbeziehung) von <code>ServiceNeeds::ServiceNeeds</code>.</li>\n<li><code>SwcEcuStateMgrUserNeeds</code>: Spezialisierung von <code>ServiceNeeds::EcuStateMgrUserNeeds</code>. Besitzt eine Komposition über die Rolle <code>+serviceCallPort</code> mit Multiplizität <code>0..*</code> zu <code>RoleBasedRPortAssignment</code>.</li>\n<li><code>RoleBasedRPortAssignment</code>: Enthält das Attribut <code>+ role: Identifier</code>. Referenziert über eine gerichtete Assoziation mit der Rolle <code>+rPortPrototype</code> und Multiplizität <code>1</code> einen Port-Prototyp.</li>\n<li><code>Components::RPortPrototype</code> (Stereotypen «PortPrototype», «atpPrototype»): Ziel der Port-Zuweisung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Metamodell-Struktur. Es stellt keine dynamischen Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert normativ die Deklaration von EcuM-Bedarfen innerhalb eines SWC-Internal-Behavior. Benötigt eine Software-Komponente Interaktionen mit dem Ecu State Manager, deklariert sie Instanzen von <code>SwcEcuStateMgrUserNeeds</code>. Die Interaktion wird über <code>RoleBasedRPortAssignment</code> an genau einen <code>RPortPrototype</code> gebunden, wobei die funktionale Rolle des Ports über das Attribut <code>role</code> qualifiziert wird. Mehrfachinstanziierung des internen Verhaltens wird über das Attribut <code>supportsMultipleInstantiation</code> geregelt.</p>"}, {"id": "FIG-701c56b1cdb2a2ca", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR-SoftwareComponentTemplate. Das Diagramm modelliert die Integration von ECU-State-Manager-Bedarfen (<code>SwcEcuStateMgrUserNeeds</code>) einer Software-Komponente in deren internes Verhalten (<code>SwcInternalBehavior::InternalBehavior</code>) sowie die Zuordnung zu konkreten Empfänger-Ports (<code>RoleBasedRPortAssignment</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SwcInternalBehavior::InternalBehavior</code> (Stereotyp «ARElement»): Enthält das Attribut <code>+ supportsMultipleInstantiation: Boolean</code>. Besitzt eine Kompositionsbeziehung über die Assoziationsrolle <code>+serviceNeeds</code> mit Multiplizität <code>0..*</code> zu <code>Identifiable / ServiceNeeds::ServiceNeeds</code>.</li>\n<li><code>ServiceNeeds::ServiceNeeds</code> (Spezialisierung von <code>Identifiable</code>): Abstrakte Basisklasse für Service-Bedarfe.</li>\n<li><code>ServiceNeeds::EcuStateMgrUserNeeds</code>: Spezialisierung (Generalisierungsbeziehung) von <code>ServiceNeeds::ServiceNeeds</code>.</li>\n<li><code>SwcEcuStateMgrUserNeeds</code>: Spezialisierung von <code>ServiceNeeds::EcuStateMgrUserNeeds</code>. Besitzt eine Komposition über die Rolle <code>+serviceCallPort</code> mit Multiplizität <code>0..*</code> zu <code>RoleBasedRPortAssignment</code>.</li>\n<li><code>RoleBasedRPortAssignment</code>: Enthält das Attribut <code>+ role: Identifier</code>. Referenziert über eine gerichtete Assoziation mit der Rolle <code>+rPortPrototype</code> und Multiplizität <code>1</code> einen Port-Prototyp.</li>\n<li><code>Components::RPortPrototype</code> (Stereotypen «PortPrototype», «atpPrototype»): Ziel der Port-Zuweisung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Metamodell-Struktur. Es stellt keine dynamischen Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert normativ die Deklaration von EcuM-Bedarfen innerhalb eines SWC-Internal-Behavior. Benötigt eine Software-Komponente Interaktionen mit dem Ecu State Manager, deklariert sie Instanzen von <code>SwcEcuStateMgrUserNeeds</code>. Die Interaktion wird über <code>RoleBasedRPortAssignment</code> an genau einen <code>RPortPrototype</code> gebunden, wobei die funktionale Rolle des Ports über das Attribut <code>role</code> qualifiziert wird. Mehrfachinstanziierung des internen Verhaltens wird über das Attribut <code>supportsMultipleInstantiation</code> geregelt.</p>"}, {"id": "FIG-7467a3972677c59e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR-SoftwareComponentTemplate. Das Diagramm modelliert die Integration von ECU-State-Manager-Bedarfen (<code>SwcEcuStateMgrUserNeeds</code>) einer Software-Komponente in deren internes Verhalten (<code>SwcInternalBehavior::InternalBehavior</code>) sowie die Zuordnung zu konkreten Empfänger-Ports (<code>RoleBasedRPortAssignment</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SwcInternalBehavior::InternalBehavior</code> (Stereotyp «ARElement»): Enthält das Attribut <code>+ supportsMultipleInstantiation: Boolean</code>. Besitzt eine Kompositionsbeziehung über die Assoziationsrolle <code>+serviceNeeds</code> mit Multiplizität <code>0..*</code> zu <code>Identifiable / ServiceNeeds::ServiceNeeds</code>.</li>\n<li><code>ServiceNeeds::ServiceNeeds</code> (Spezialisierung von <code>Identifiable</code>): Abstrakte Basisklasse für Service-Bedarfe.</li>\n<li><code>ServiceNeeds::EcuStateMgrUserNeeds</code>: Spezialisierung (Generalisierungsbeziehung) von <code>ServiceNeeds::ServiceNeeds</code>.</li>\n<li><code>SwcEcuStateMgrUserNeeds</code>: Spezialisierung von <code>ServiceNeeds::EcuStateMgrUserNeeds</code>. Besitzt eine Komposition über die Rolle <code>+serviceCallPort</code> mit Multiplizität <code>0..*</code> zu <code>RoleBasedRPortAssignment</code>.</li>\n<li><code>RoleBasedRPortAssignment</code>: Enthält das Attribut <code>+ role: Identifier</code>. Referenziert über eine gerichtete Assoziation mit der Rolle <code>+rPortPrototype</code> und Multiplizität <code>1</code> einen Port-Prototyp.</li>\n<li><code>Components::RPortPrototype</code> (Stereotypen «PortPrototype», «atpPrototype»): Ziel der Port-Zuweisung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Metamodell-Struktur. Es stellt keine dynamischen Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert normativ die Deklaration von EcuM-Bedarfen innerhalb eines SWC-Internal-Behavior. Benötigt eine Software-Komponente Interaktionen mit dem Ecu State Manager, deklariert sie Instanzen von <code>SwcEcuStateMgrUserNeeds</code>. Die Interaktion wird über <code>RoleBasedRPortAssignment</code> an genau einen <code>RPortPrototype</code> gebunden, wobei die funktionale Rolle des Ports über das Attribut <code>role</code> qualifiziert wird. Mehrfachinstanziierung des internen Verhaltens wird über das Attribut <code>supportsMultipleInstantiation</code> geregelt.</p>"}], "trans": [{"from": "FIG-3fa196727afaa99e", "to": "FIG-701c56b1cdb2a2ca", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-701c56b1cdb2a2ca", "to": "FIG-7467a3972677c59e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>SwcInternalBehavior::InternalBehavior</code>: Leerraum vor dem Doppelpunkt im Attribut <code>+ supportsMultipleInstantiation :Boolean</code> eingefügt.</li>\n<li><code>RoleBasedRPortAssignment</code>: Leerraum vor dem Doppelpunkt im Attribut <code>+ role :Identifier</code> eingefügt.</li>\n<li>Gesamtdiagramm: Neuberechnung und Skalierung der Grafikabmessungen.</li>\n</ul>"}]};
